#!/usr/bin/env python3
# Writes the generated src/shared/SidekickArt.luau from the two upload ledgers. Sidekicks are not characters (design doc 4.36):
# they stay out of CharacterModelAssets, CharacterPortraits and CharacterHeads, which feed rollable-character code and tests.
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
REGISTRY = os.path.join(os.path.dirname(os.path.dirname(HERE)), "src", "shared", "SidekickArt.luau")


def is_sidekick(cid):
	return cid.startswith("side_")


def lines(models, images):
	out = [
		"--!nonstrict",
		"-- Generated by tools/blender/sidekick_art.py: Sidekick id -> uploaded Model asset and drawn images. Do not edit by hand.",
		"-- docs/SIDEKICK_SPEC.md. A field with no upload yet is absent.",
		"return {",
	]
	for cid in sorted(c for c in {*models, *images} if is_sidekick(c)):
		row = images.get(cid, {})
		fields = []
		if cid in models:
			fields.append("Model = %s" % models[cid])
		if row.get("Image"):
			fields.append('Portrait = "rbxassetid://%s"' % row["Image"])
		if row.get("HeadImage"):
			fields.append('Head = "rbxassetid://%s"' % row["HeadImage"])
		out += ["\t%s = {" % cid, *["\t\t%s," % f for f in fields], "\t},"]
	out.append("}\n")
	return out


def write():
	found = []
	for name in ("avatar_assets.json", "portrait_assets.json"):
		path = os.path.join(HERE, name)
		found.append(json.load(open(path)) if os.path.exists(path) else {})
	with open(REGISTRY, "w") as f:
		f.write("\n".join(lines(*found)))


assert lines({"side_a": "1", "db_hero": "2"}, {"side_a": {"Image": "3"}, "db_hero": {"Image": "4"}})[4:] == ["\tside_a = {", "\t\tModel = 1,", '\t\tPortrait = "rbxassetid://3",', "\t},", "}\n"]
